import React from 'react';
import { useNavigate } from 'react-router-dom';  // Atualize a importação
 // Para o redirecionamento
import '../../visualPage/CadastroTurmas.css';  // Importa o arquivo de CSS

function CadastroTurmas() {
  const history = useHistory(); // Hook para manipular navegação

  const handleBack = () => {
    history.push('/'); // Redireciona para a página inicial
  };

  return (
    <div className="construction-container">
      <h1 className="construction-title">🚧 EM CONSTRUÇÃO 🚧</h1>
      <p className="construction-description">
        A página de Turma ainda está em desenvolvimento. Volte mais tarde!
      </p>
      <button className="back-button" onClick={handleBack}>
        OK
      </button>
    </div>
  );
}

export default CadastroTurmas;
